from itertools import combinations
cols={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'P4':P**4,'sqrtP':np.sqrt(P),'1/P':1/P,'logP':np.log(P),'t':t,'tP':t*P,'expP':np.exp(-P),'Pexp':P*np.exp(-P)}
names=list(cols)
best=[]
for k in [2,3]:
    for comb in combinations(names,k):
        A=np.c_[[cols[n] for n in comb]].T
        c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
        r=np.mean((A@c-dP_dt)**2)/np.var(dP_dt)
        best.append((r,comb,np.round(c,4)))
best.sort(key=lambda x:x[0])
for b in best[:8]: print(b)
